window.FRONTEND_CONTROLS={"controls":[{"name":"InputTextBox","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/InputTextBox.cs","summary":"通用输入框：框架里的文本、数值输入都用它。界面绑 Value（提交后的合法值），不要绑 Text（正在输入的原文）。 校验分两步，免得\"范围 2~20 想输 10，敲下 1 就报错\"： ① 边输入边查格式——只拦不可能再变合法的输入（整数里敲了字母、小数里两个小数点），\"-\"、\"1.\" 这种没输完的不算错； ② 回车或离开输入框时提交——查完整格式和范围，合法才写进 Value，不合法红框提示、Value 保留上一次的合法值。 类型和范围：界面上写的（DataType / Minimum / Maximum / Unit）优先；没写的按 EcKey 从 EC 取（格式、上下限、单位）； 都没配就是普通输入框，不校验。文本类型没有上下限的概念，只有整数、小数才查范围。","is3D":false,"project":false,"properties":[{"name":"Value","type":"String","default":"空字符串","readOnly":false,"twoWay":true,"owner":"InputTextBox","description":"提交后的合法值（双向绑定）。整数、小数按不变区域性写（小数点是点号），绑到数值属性由绑定自动转换。","enumValues":[]},{"name":"DataType","type":"InputDataType","default":"Text","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"数据类型；不写就按 EC 的格式（Int → 整数，Double → 小数），再没有就是文本。","enumValues":["Text","Integer","Decimal"]},{"name":"Minimum","type":"Double?","default":"null","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"最小值（含）；不写就用 EC 的下限，再没有就不限。文本类型不生效。","enumValues":[]},{"name":"Maximum","type":"Double?","default":"null","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"最大值（含）；不写就用 EC 的上限，再没有就不限。文本类型不生效。","enumValues":[]},{"name":"Unit","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"单位，只用在范围提示里（如\"范围 2 ~ 20 L/min\"）；不写就用 EC 的单位。","enumValues":[]},{"name":"EcKey","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"从哪项 EC 取类型、范围、单位：\"元件全路径.参数名\"，如 LoadPort1.LoadTimeout、Chamber1.Door.ActionTimeoutMs。 可以绑定（按模块拼出来的键）；EC 里没有这项就当没配。","enumValues":[]},{"name":"ErrorMessage","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"自定义错误提示：给了就一律显示它，可用 {0} {1} 占最小、最大值；不给用语言包里的默认提示。","enumValues":[]},{"name":"HasError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"InputTextBox","description":"当前输入有没有错（格式不对，或提交时范围不对）。外面可以 OneWayToSource 绑出去，比如错着的时候不让下发。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"InputTextBox-0.png","mesh":null},{"label":"整数","values":{"DataType":"Integer"},"image":"InputTextBox-1.png","mesh":null},{"label":"错误状态","values":{"HasError":"true"},"image":"InputTextBox-2.png","mesh":null}],"error":null,"example":"<controls:InputTextBox\n    Value=\"{Binding TargetFlow}\"\n    DataType=\"Decimal\"\n    Minimum=\"0\"\n    Maximum=\"100\"\n    Unit=\"L/min\"\n    HasError=\"{Binding FlowHasError, Mode=OneWayToSource}\" />","group":"输入与操作"},{"name":"DateTimePicker","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/DateTimePicker.xaml.cs","summary":"日期时间选择：日期框 + \"时\"下拉（00~23）+ \"分\"下拉（00~59），精确到分钟。报警历史、日志历史、数据曲线的查询时间段都用它。 绑 Value（双向）；日期清空时 Value 为 null，由页面按自己的默认值处理。","is3D":false,"project":false,"properties":[{"name":"Value","type":"DateTime?","default":"null","readOnly":false,"twoWay":true,"owner":"DateTimePicker","description":"选中的时刻（秒一律为 0）。","enumValues":[]},{"name":"Hint","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"DateTimePicker","description":"提示文字（开始时间、结束时间……），显示在日期框上。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"DateTimePicker-0.png","mesh":null}],"error":null,"example":"<controls:DateTimePicker\n    Value=\"{Binding StartTime}\"\n    Hint=\"{DynamicResource common.start_time}\" />","group":"输入与操作"},{"name":"PickerBox","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/PickerBox.xaml.cs","summary":"公共选择框：从一个库里选一项（如流程配方里选工艺配方）不用下拉框，用它——左边显示选中的值，右边\"…\"点开公共选择弹窗。 弹窗里显示什么由用的地方给：标题（PickerTitle）、列（Columns）、数据（ItemsSource）、选中后回填哪个属性（ValuePath）。 用法跟 InputTextBox 一样绑 Value；宽高直接设 Width / Height，或者用 DefaultPickerBoxStyle / ToolbarPickerBoxStyle / CompactPickerBoxStyle。","is3D":false,"project":false,"properties":[{"name":"Value","type":"String","default":"空字符串","readOnly":false,"twoWay":true,"owner":"PickerBox","description":"选中的值（双向绑定）：弹窗里选中那一项的 ValuePath 属性；能手输时也是输入的字。","enumValues":[]},{"name":"Placeholder","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"没有值时框里的提示字。","enumValues":[]},{"name":"PickerTitle","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"弹窗标题。","enumValues":[]},{"name":"ItemsSource","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"弹窗里列出来的数据。","enumValues":[]},{"name":"ValuePath","type":"String","default":"Name","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"选中后把数据项的哪个属性填回 Value（默认 Name）。","enumValues":[]},{"name":"IsEditable","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"能不能手输：默认不能（只能从弹窗里选，免得打错名字）。","enumValues":[]},{"name":"HasError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"PickerBox","description":"值不对（没选、选的不存在……）：框变红。","enumValues":[]}],"members":[{"name":"Columns","type":"ObservableCollection<PickerColumn>","description":"弹窗里显示哪几列，在 XAML 里写。"}],"variants":[{"label":"基础示例","values":{},"image":"PickerBox-0.png","mesh":null}],"error":null,"example":"<controls:PickerBox\n    Value=\"{Binding RecipeName}\"\n    ItemsSource=\"{Binding Recipes}\"\n    ValuePath=\"Name\"\n    PickerTitle=\"选择配方\"\n    Placeholder=\"请选择\">\n    <controls:PickerBox.Columns>\n        <controls:PickerColumn HeaderKey=\"common.name\" Path=\"Name\" />\n    </controls:PickerBox.Columns>\n</controls:PickerBox>","group":"输入与操作"},{"name":"HoldButton","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/HoldButton.cs","summary":"按住类按钮（点动）：按下发一次 PressCommand；松开、鼠标拖出按钮、按钮被禁用或藏起来都发 ReleaseCommand，中间不发别的。 两个命令共用 CommandParameter。不用 Button.Command（那是松开时才触发的单击）。松手一定要发出去，所以 Release 不看 CanExecute。 样式照普通按钮写（Style 的 TargetType 写 Button 也能套）。","is3D":false,"project":false,"properties":[{"name":"PressCommand","type":"ICommand","default":"null","readOnly":false,"twoWay":false,"owner":"HoldButton","description":"按下时发（如点动开始）。","enumValues":[]},{"name":"ReleaseCommand","type":"ICommand","default":"null","readOnly":false,"twoWay":false,"owner":"HoldButton","description":"松手时发（如停止）。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"HoldButton-0.png","mesh":null}],"error":null,"example":"<controls:HoldButton\n    Content=\"按住点动\"\n    PressCommand=\"{Binding JogStartCommand}\"\n    ReleaseCommand=\"{Binding JogStopCommand}\" />","group":"输入与操作"},{"name":"SignalLamp","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/SignalLamp.xaml.cs","summary":"信号灯：一盏灯 + 名字，对一个 DI 信号","is3D":false,"project":false,"properties":[{"name":"Text","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"SignalLamp","description":"名字（machine.xml 里的节点名，原样显示）","enumValues":[]},{"name":"IsActive","type":"Boolean?","default":"null","readOnly":false,"twoWay":false,"owner":"SignalLamp","description":"有没有触发，读不到是 null","enumValues":[]},{"name":"IsAlarm","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"SignalLamp","description":"报警位（HH、Overfill 这种）：触发了亮红","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"SignalLamp-0.png","mesh":null},{"label":"触发","values":{"IsActive":"true"},"image":"SignalLamp-1.png","mesh":null},{"label":"未触发","values":{"IsActive":"false"},"image":"SignalLamp-2.png","mesh":null},{"label":"未知","values":{"IsActive":"null"},"image":"SignalLamp-3.png","mesh":null},{"label":"报警位触发","values":{"IsAlarm":"true"},"image":"SignalLamp-4.png","mesh":null}],"error":null,"example":"<controls:SignalLamp\n    Text=\"Tank1.H\"\n    IsActive=\"{Binding Tank.H.IsActive}\"\n    IsAlarm=\"False\" />","group":"信号与状态"},{"name":"SignalTower","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/SignalTower.xaml.cs","summary":"四色灯（竖排）：红 = 报警、黄 = 警告、绿 = 运行、蓝 = 通讯。只管显示，亮不亮由外面绑定四个开关。","is3D":false,"project":false,"properties":[{"name":"IsRedOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"SignalTower","description":"红灯：报警。","enumValues":[]},{"name":"IsYellowOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"SignalTower","description":"黄灯：警告。","enumValues":[]},{"name":"IsGreenOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"SignalTower","description":"绿灯：运行。","enumValues":[]},{"name":"IsBlueOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"SignalTower","description":"蓝灯：通讯。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"SignalTower-0.png","mesh":null},{"label":"红灯","values":{"IsRedOn":"true"},"image":"SignalTower-1.png","mesh":null},{"label":"黄灯","values":{"IsYellowOn":"true"},"image":"SignalTower-2.png","mesh":null}],"error":null,"example":"<controls:SignalTower\n    IsRedOn=\"{Binding HasAlarm}\"\n    IsYellowOn=\"{Binding HasWarning}\"\n    IsGreenOn=\"{Binding IsRunning}\"\n    IsBlueOn=\"{Binding IsConnected}\" />","group":"信号与状态"},{"name":"TrendChart","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/TrendChart.ReferenceLines.cs","summary":"趋势图的基准线（右上角 X、Y 两个按钮开关）：X 两条竖线量时间差，Y 两条横线量数值差。 线比曲线粗、画在曲线下面；按住线（6 像素以内）或轴上的标签就能拖，离线远的地方左键照旧平移。 线钉在数据上（X 是时刻、Y 是纵轴上的值），缩放、平移以后还在原处；打开时原来的位置不在眼前，就放到当前这一段的 1/3、2/3。 X1、X2 的时刻标在时间轴上，Y1、Y2 的值标在纵轴上（被压住的刻度不写字）；两条线之间一个双向箭头标出差（ΔX、ΔY）。 开着 X 线时，每条曲线在 X1、X2 那一刻的值写进 TrendSeries.ValueAtX1 / ValueAtX2，信息表从那儿显示。","is3D":false,"project":false,"properties":[{"name":"ShowXLines","type":"Boolean","default":"false","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"显示 X 基准线（两条竖线）；右上角 X 按钮开关。","enumValues":[]},{"name":"ShowYLines","type":"Boolean","default":"false","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"显示 Y 基准线（两条横线）；右上角 Y 按钮开关。","enumValues":[]},{"name":"Series","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"TrendChart","description":"要画的曲线（TrendSeries 的集合，ObservableCollection 增删会跟着变）。","enumValues":[]},{"name":"RangeStart","type":"DateTime?","default":"null","readOnly":false,"twoWay":false,"owner":"TrendChart","description":"整段的起点（数据曲线是查询的时间段，实时曲线是最近 N 分钟）。","enumValues":[]},{"name":"RangeEnd","type":"DateTime?","default":"null","readOnly":false,"twoWay":false,"owner":"TrendChart","description":"完整数据区间的起止时间；不等于用户当前缩放后的可见区间。","enumValues":[]},{"name":"FollowRange","type":"Boolean","default":"true","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"横轴跟着整段走；用户缩放、平移、框选时自动变假（停在他看的地方），双击回到整段时变真。","enumValues":[]},{"name":"VisibleStart","type":"DateTime?","default":"null","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"当前看到的时间段（每次重画后更新）。","enumValues":[]},{"name":"VisibleEnd","type":"DateTime?","default":"null","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"当前画面可见时间范围的输出值；通常使用双向绑定读取。","enumValues":[]},{"name":"CursorTime","type":"DateTime?","default":"null","readOnly":false,"twoWay":true,"owner":"TrendChart","description":"鼠标对准的时刻（对准了采样点就是那个点的时刻）；鼠标不在绘图区为 null。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"TrendChart-0.png","mesh":null}],"error":null,"example":"<controls:TrendChart\n    Series=\"{Binding Series}\"\n    RangeStart=\"{Binding StartTime}\"\n    RangeEnd=\"{Binding EndTime}\"\n    FollowRange=\"{Binding FollowRange}\"\n    VisibleStart=\"{Binding VisibleStart}\"\n    VisibleEnd=\"{Binding VisibleEnd}\"\n    CursorTime=\"{Binding CursorTime}\" />","group":"数据与设备卡片"},{"name":"Wafer","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/Wafer.xaml.cs","summary":"Wafer 控件（由 GR 的 Disk 控件改名为 Wafer）。","is3D":false,"project":false,"properties":[{"name":"Data","type":"Object","default":"null","readOnly":false,"twoWay":false,"owner":"Wafer","description":"控件要显示的数据对象；晶圆控件通常接收 WaferModel。","enumValues":[]},{"name":"IsDiskVisible","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"Wafer","description":"无业务数据时是否仍显示 Wafer 图形。","enumValues":[]},{"name":"FillColor","type":"Brush","default":"#FF808080","readOnly":false,"twoWay":false,"owner":"Wafer","description":"圆盘填充画刷；有匹配的晶圆业务状态时优先使用状态色。","enumValues":[]},{"name":"Label","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"Wafer","description":"圆片文字覆盖值；三维 Disk 支持覆盖，二维 Wafer 当前模板仍显示 Data.LpSlot。","enumValues":[]},{"name":"RotationSpeed","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"Wafer","description":"显示旋转速度（度/秒），不能把设备 RPM 不经换算直接绑定。","enumValues":[]},{"name":"RotateClockwise","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"Wafer","description":"从上方观察时的旋转方向，true 为顺时针；RotationSpeed 仍使用度/秒。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"Wafer-0.png","mesh":null}],"error":null,"example":"<controls:Wafer\n    Data=\"{Binding Wafer}\"\n    IsDiskVisible=\"True\"\n    RotationSpeed=\"{Binding DisplayDegreesPerSecond}\" />","group":"数据与设备卡片"},{"name":"AlarmBar","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/AlarmBar.xaml.cs","summary":"顶栏报警栏：当前报警的条数和最新一条，展开看全部。控件自带 ViewModel，放到任意窗口即可用。","is3D":false,"project":false,"properties":[],"members":[{"name":"ViewModel","type":"AlarmBarViewModel","description":"报警栏 ViewModel。"}],"variants":[{"label":"基础示例","values":{},"image":"AlarmBar-0.png","mesh":null}],"error":null,"example":"<controls:AlarmBar />","group":"信号与状态"},{"name":"BottomChamberInfoCard","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/BottomChamberInfoCard.xaml.cs","summary":"标题栏位于底部的独立腔体信息卡片控件。","is3D":false,"project":false,"properties":[{"name":"Title","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"卡片标题；绑定模块显示名，不承担设备身份或指令路由。","enumValues":[]},{"name":"StatusOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"状态指示开关；true 显示点亮状态，false 显示未点亮状态。","enumValues":[]},{"name":"IsOnline","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"连接状态显示文本；注意本控件该属性的类型是字符串。","enumValues":[]},{"name":"State","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"显示状态；按本行类型绑定，字符串状态和 ProgressState 对象不能混用。","enumValues":[]},{"name":"RecipeState","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"配方执行状态的显示文本。","enumValues":[]},{"name":"Recipe","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"当前配方名的显示文本。","enumValues":[]},{"name":"Step","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"当前工艺步骤的显示文本。","enumValues":[]},{"name":"StepTime","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"当前步骤时间的显示值；查看本行类型决定传文本还是数值。","enumValues":[]},{"name":"RecipeTime","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"整份配方时间的显示值。","enumValues":[]},{"name":"ShutterState","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"腔门或挡板状态的显示文本。","enumValues":[]},{"name":"Wafer","type":"WaferModel","default":"null","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"当前位置的晶圆显示数据；没有片时传 null，不创建后端晶圆账。","enumValues":[]},{"name":"RotationSpeed","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"BottomChamberInfoCard","description":"显示旋转速度（度/秒），不能把设备 RPM 不经换算直接绑定。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"BottomChamberInfoCard-0.png","mesh":null}],"error":null,"example":"<controls:BottomChamberInfoCard\n    Title=\"Chamber1\"\n    State=\"{Binding StateText}\"\n    IsOnline=\"{Binding ConnectionText}\"\n    Wafer=\"{Binding Wafer}\"\n    Recipe=\"{Binding Recipe}\" />","group":"数据与设备卡片"},{"name":"Buffer","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/Buffer.xaml.cs","summary":"Buffer 模块卡片：标题和状态围绕可独立使用的 BufferView，数据与交互由内层视图处理。","is3D":false,"project":false,"properties":[{"name":"Title","type":"String","default":"Buffer","readOnly":false,"twoWay":false,"owner":"Buffer","description":"卡片标题；绑定模块显示名，不承担设备身份或指令路由。","enumValues":[]},{"name":"StateText","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"Buffer","description":"状态文案由调用方提供，空字符串不显示徽标。","enumValues":[]},{"name":"StateTone","type":"ModuleStateTone","default":"Inactive","readOnly":false,"twoWay":false,"owner":"Buffer","description":"状态色调；使用属性类型对应的枚举值，不直接传后端整数。","enumValues":["Inactive","Busy","Ready","Warning","Alarm"]},{"name":"IsProduction","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"Buffer","description":"生产模式（交给调度用）亮，维护灭","enumValues":[]},{"name":"FirstSlot","type":"Int32","default":"1","readOnly":false,"twoWay":false,"owner":"Buffer","description":"最底层的物理槽号；用于显示同一个架子的某个槽段，默认 1。","enumValues":[]},{"name":"SlotCount","type":"Int32","default":"10","readOnly":false,"twoWay":false,"owner":"Buffer","description":"实际槽数，默认 10；0 显示空视图。固定槽距，增减槽数后自动重新取景。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"Buffer","description":"WaferModel 集合，按物理 Slot 摆片、State 上色；支持集合增删、替换及单片 Slot/State 变化。 范围外的片不显示，同槽重复只显示第一片；不按 LoadPort 的来源槽号推断位置。 集合与模型应像其它 WPF 绑定数据一样在 UI 线程更新。","enumValues":[]},{"name":"WaferCount","type":"Int32","default":"0","readOnly":true,"twoWay":false,"owner":"Buffer","description":"当前显示的片数，只读，按实际有效占用槽统计。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"Buffer-0.png","mesh":null},{"label":"8 个槽（示例）","values":{"SlotCount":"8"},"image":"Buffer-1.png","mesh":null}],"error":null,"example":"<controls:Buffer\n    Title=\"Buffer1\"\n    FirstSlot=\"1\"\n    SlotCount=\"{Binding SlotCount}\"\n    Wafers=\"{Binding Wafers}\"\n    StateText=\"{Binding StateText}\"\n    IsProduction=\"{Binding IsProduction}\" />","group":"数据与设备卡片"},{"name":"BufferView","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/BufferView.xaml.cs","summary":"可直接放进 Grid 的独立缓存架视图。自带相机和灯光，继承页面 DataContext； 没有模块标题、状态栏、计数文字或按钮。拖动旋转、滚轮缩放，不提供选片操作。","is3D":true,"project":false,"properties":[{"name":"FirstSlot","type":"Int32","default":"1","readOnly":false,"twoWay":false,"owner":"BufferView","description":"最底层物理槽号；与 SlotCount 一起定义有效槽位范围。","enumValues":[]},{"name":"SlotCount","type":"Int32","default":"10","readOnly":false,"twoWay":false,"owner":"BufferView","description":"实际槽位数量，应来自装机或后端快照；文档演示值只是样例。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"BufferView","description":"晶圆集合，按 WaferModel.Slot 放入槽位；集合变更监听策略见控件使用说明。","enumValues":[]},{"name":"WaferCount","type":"Int32","default":"0","readOnly":true,"twoWay":false,"owner":"BufferView","description":"当前有效占用槽数，只读；可作为其他控件绑定的来源。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"BufferView-0.png","mesh":"BufferView-0.mesh.js"},{"label":"8 个槽（示例）","values":{"SlotCount":"8"},"image":"BufferView-1.png","mesh":"BufferView-1.mesh.js"}],"error":null,"example":"<controls:BufferView\n    FirstSlot=\"1\"\n    SlotCount=\"{Binding SlotCount}\"\n    Wafers=\"{Binding Wafers}\" />","group":"3D 组合视图"},{"name":"ChamberInfoCard","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ChamberInfoCard.xaml.cs","summary":"近方形腔体信息卡片，参考 GR 调度界面的 ChamberInfoCard：标题行带缩小版状态徽标，左五行字段 + 右圆片。按真实字号排版、随给定尺寸伸缩，不整卡缩放。 字段哪一行没有值就整行不显示（现在后端只给配方，步骤、腔门、时间这些有了数据才出来）。","is3D":false,"project":false,"properties":[{"name":"Title","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"卡片标题；绑定模块显示名，不承担设备身份或指令路由。","enumValues":[]},{"name":"Number","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"站点号角标（机械手示教点表里的设备站点号）；空就不显示。","enumValues":[]},{"name":"DiskSize","type":"Double","default":"100","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"圆片直径：跟调度图里机械手叉上的片一样大，由页面按机械手的显示尺寸给。","enumValues":[]},{"name":"StatusOn","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"状态指示开关；true 显示点亮状态，false 显示未点亮状态。","enumValues":[]},{"name":"IsOnline","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"连接状态显示文本；注意本控件该属性的类型是字符串。","enumValues":[]},{"name":"StateText","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"腔体状态文字，标题行右侧缩小版状态徽标显示；空就不显示徽标。","enumValues":[]},{"name":"StateTone","type":"ModuleStateTone","default":"Inactive","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"腔体状态色调（徽标底色）。","enumValues":["Inactive","Busy","Ready","Warning","Alarm"]},{"name":"RecipeState","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"配方执行状态的显示文本。","enumValues":[]},{"name":"Recipe","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"当前配方名的显示文本。","enumValues":[]},{"name":"Step","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"当前工艺步骤的显示文本。","enumValues":[]},{"name":"StepTime","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"当前步骤时间的显示值；查看本行类型决定传文本还是数值。","enumValues":[]},{"name":"RecipeTime","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"整份配方时间的显示值。","enumValues":[]},{"name":"ShutterState","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"腔门或挡板状态的显示文本。","enumValues":[]},{"name":"Wafer","type":"WaferModel","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"当前位置的晶圆显示数据；没有片时传 null，不创建后端晶圆账。","enumValues":[]},{"name":"RotationSpeed","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"ChamberInfoCard","description":"显示旋转速度（度/秒），不能把设备 RPM 不经换算直接绑定。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"ChamberInfoCard-0.png","mesh":null}],"error":null,"example":"<controls:ChamberInfoCard\n    Title=\"Chamber1\"\n    Number=\"1\"\n    StateText=\"{Binding StateText}\"\n    StateTone=\"{Binding StateTone}\"\n    Wafer=\"{Binding Wafer}\"\n    Recipe=\"{Binding Recipe}\" />","group":"数据与设备卡片"},{"name":"ChamberView","namespace":"xyz._35021.Client.Presentation.Controls","source":"xyz.35021/Client/Presentation/Controls/ChamberView.xaml.cs","summary":"35021 正式腔体图。加载布局数据，全部动作取后台反馈；没有布局编辑或模拟指令。","is3D":true,"project":true,"properties":[{"name":"Snapshot","type":"ChamberDeviceDataDto","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberView","description":"完整设备快照；设备组成由实际快照决定，布局不能添加不存在的硬件。","enumValues":[]},{"name":"Layout","type":"ChamberLayoutModel","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberView","description":"ToolBuilder 导出的显示布局；仅描述位置、大小与父子挂载关系。","enumValues":[]},{"name":"VisualCatalog","type":"ChamberVisualCatalog","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberView","description":"项目控件提供者目录；已实现的项目控件优先，缺少的种类使用平台外观。","enumValues":[]},{"name":"Wafer","type":"Object","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberView","description":"当前位置的晶圆显示数据；没有片时传 null，不创建后端晶圆账。","enumValues":[]}],"members":[{"name":"DisplayedParts","type":"IReadOnlyDictionary<string, ChamberPartVisual>","description":""}],"variants":[{"label":"基础示例","values":{},"image":"ChamberView-0.png","mesh":"ChamberView-0.mesh.js"}],"error":null,"example":"<project:ChamberView\n    Snapshot=\"{Binding Snapshot}\"\n    Layout=\"{Binding Layout}\"\n    VisualCatalog=\"{Binding VisualCatalog}\"\n    Wafer=\"{Binding Wafer}\" />","group":"项目控件"},{"name":"DispatchMap","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/DispatchMap.xaml.cs","summary":"调度图（公共控件，Robot 手动页和主界面都用）：给一个机械手模块名，控件自己建 ViewModel、订推送， 机械手画在中间，站点卡片按它示教点表里的方向摆在四周——machine.xml 里多一个腔体、一个 LoadPort，图上就多一张卡片，不用改界面。 机型的主界面要别的摆法（两台机械手、缓存位……）时，自己写调度图，照样可以拿它、StationCard、Robot 来拼。","is3D":false,"project":false,"properties":[{"name":"RobotName","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"DispatchMap","description":"机械手模块名（如 Robot1），也是它状态推送的 token；换了就重建 ViewModel、重订推送。","enumValues":[]},{"name":"CardWidth","type":"Double","default":"280","readOnly":false,"twoWay":false,"owner":"DispatchMap","description":"站点卡片宽（默认 280，近方形）。","enumValues":[]},{"name":"CardHeight","type":"Double","default":"233","readOnly":false,"twoWay":false,"owner":"DispatchMap","description":"站点卡片高（默认 233）。","enumValues":[]},{"name":"RobotHeight","type":"Double","default":"360","readOnly":false,"twoWay":false,"owner":"DispatchMap","description":"机械手画多高（默认 360）；卡片上的圆片跟着它算，跟叉上的片一样大。","enumValues":[]},{"name":"DiskSize","type":"Double","default":"75.6","readOnly":true,"twoWay":false,"owner":"DispatchMap","description":"卡片上圆片的直径 = 机械手叉上的片按 RobotHeight 缩放后的大小（只读，跟着 RobotHeight 变）。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"DispatchMap-0.png","mesh":null}],"error":null,"example":"<controls:DispatchMap\n    RobotName=\"Robot1\"\n    CardWidth=\"280\"\n    CardHeight=\"233\"\n    RobotHeight=\"360\" />","group":"数据与设备卡片"},{"name":"FluidPipe","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/FluidPipe.xaml.cs","summary":"可直接放进 Grid、Canvas、StackPanel 的管路控件。 默认是一根直管；设置 Points 后按二维路径绘制，相机和灯光由控件内部管理。","is3D":false,"project":false,"properties":[{"name":"Points","type":"PointCollection","default":"null","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"管中心的二维路径点，X 向右、Y 向下。不设置时按控件大小显示直管。","enumValues":[]},{"name":"Orientation","type":"Orientation","default":"Horizontal","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"默认直管的方向。设置 Points 后按路径绘制。","enumValues":["Horizontal","Vertical"]},{"name":"PipeThickness","type":"Double","default":"14","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"管外直径，使用 WPF 逻辑像素。","enumValues":[]},{"name":"WallThickness","type":"Double","default":"2","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"管壁厚度，使用 WPF 逻辑像素。","enumValues":[]},{"name":"BendRadius","type":"Double","default":"24","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"转弯圆角半径，使用路径坐标单位。","enumValues":[]},{"name":"FluidCoreRatio","type":"Double","default":"0.58","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"液芯半径占内腔半径的比例，范围为 (0, 1]。","enumValues":[]},{"name":"WallOpacity","type":"Double","default":"0.18","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"管壁不透明度强度，范围为 [0, 1]，越小越透明。","enumValues":[]},{"name":"WallColor","type":"Color","default":"#FFB4B4B4","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"管壁颜色。","enumValues":[]},{"name":"FluidColor","type":"Color","default":"#FFC4C4C4","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"液体底色，与 FlowColor 按 1:3 混合。","enumValues":[]},{"name":"FlowColor","type":"Color","default":"#FF52D4EF","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"水流主色和移动水纹的颜色。","enumValues":[]},{"name":"IsFilled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"是否有液体。false 时不显示液芯。","enumValues":[]},{"name":"IsFlowing","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"是否流动。false 时清除液芯和水纹，只显示管壁。","enumValues":[]},{"name":"FlowSpeed","type":"Double","default":"55","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"水纹每秒移动的路径长度，0 时暂停；不是设备实测流量。","enumValues":[]},{"name":"ReverseFlow","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"是否沿路径反向流动。","enumValues":[]},{"name":"IsAnimationEnabled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"FluidPipe","description":"动画开关。false 时冻结水纹，保留液芯和流动状态。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"FluidPipe-0.png","mesh":null},{"label":"出液显示","values":{"IsFlowing":"true"},"image":"FluidPipe-1.png","mesh":null},{"label":"关闭动画","values":{"IsAnimationEnabled":"false"},"image":"FluidPipe-2.png","mesh":null}],"error":null,"example":"<controls:FluidPipe\n    Points=\"{Binding PipePoints}\"\n    PipeThickness=\"16\"\n    WallThickness=\"1.6\"\n    BendRadius=\"18\"\n    IsFilled=\"True\"\n    IsFlowing=\"{Binding IsFlowing}\" />","group":"数据与设备卡片"},{"name":"Foup","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/Foup.xaml.cs","summary":"可等比缩放的 FOUP 图形组件。","is3D":false,"project":false,"properties":[],"members":[],"variants":[{"label":"基础示例","values":{},"image":"Foup-0.png","mesh":null}],"error":null,"example":"<controls:Foup\n    Width=\"240\"\n    Height=\"280\" />","group":"数据与设备卡片"},{"name":"LoadPortInfoCard","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/LoadPortInfoCard.xaml.cs","summary":"标题栏位于底部的近方形 LoadPort 信息卡片：底栏标题 + 状态灯；主体左花篮（槽数跟 machine.xml 的 SlotCount，一槽一条细线）右 disk 圆片 + 槽数。 按真实字号排版、随给定尺寸伸缩，不整卡缩放。调度图下排两颗 LP 用它。","is3D":false,"project":false,"properties":[{"name":"Title","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"卡片标题；绑定模块显示名，不承担设备身份或指令路由。","enumValues":[]},{"name":"Number","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"站点号角标（机械手示教点表里的设备站点号）；空就不显示。","enumValues":[]},{"name":"DiskSize","type":"Double","default":"100","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"圆片直径：跟调度图里机械手叉上的片一样大，由页面按机械手的显示尺寸给。","enumValues":[]},{"name":"IsOnline","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"底栏 Online 文案。","enumValues":[]},{"name":"StateText","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"LoadPort 状态文字，标题行右侧缩小版状态徽标显示；空就不显示徽标。","enumValues":[]},{"name":"StateTone","type":"ModuleStateTone","default":"Inactive","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"LoadPort 状态色调（徽标底色）。","enumValues":["Inactive","Busy","Ready","Warning","Alarm"]},{"name":"IsConnected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"通讯灯：驱动串口是否连上。","enumValues":[]},{"name":"Present","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"在位灯：FOUP 是否放上。","enumValues":[]},{"name":"Placed","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"到位灯：FOUP 是否夹紧放平。","enumValues":[]},{"name":"Alarm","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"报警灯：设备硬件报警。","enumValues":[]},{"name":"AutoMode","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"AUTO / MANUAL 灯：true=Auto，false=Manual。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"花篮里的片（有片的槽位）；槽数由 SlotCount 决定。","enumValues":[]},{"name":"SlotCount","type":"Int32","default":"0","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"花篮槽数（machine.xml 的 LoadPort.SlotCount）；0 表示还不知道、不画槽。","enumValues":[]},{"name":"Wafer","type":"WaferModel","default":"null","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"右侧 disk 圆片上的片（与 ChamberCard 同字段）。","enumValues":[]},{"name":"RotationSpeed","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"LoadPortInfoCard","description":"显示旋转速度（度/秒），不能把设备 RPM 不经换算直接绑定。","enumValues":[]}],"members":[{"name":"Slots","type":"ObservableCollection<LoadPortSlot>","description":""}],"variants":[{"label":"基础示例","values":{},"image":"LoadPortInfoCard-0.png","mesh":null}],"error":null,"example":"<controls:LoadPortInfoCard\n    Title=\"LoadPort1\"\n    SlotCount=\"{Binding SlotCount}\"\n    Wafers=\"{Binding Wafers}\"\n    Present=\"{Binding Present}\"\n    Placed=\"{Binding Placed}\"\n    StateText=\"{Binding StateText}\"\n    StateTone=\"{Binding StateTone}\" />","group":"数据与设备卡片"},{"name":"LogBar","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/LogBar.xaml.cs","summary":"顶栏日志下拉框：显示后端日志（经事件流）与客户端自身报错。 控件自带 ViewModel，放到任意窗口即可用。","is3D":false,"project":false,"properties":[],"members":[{"name":"ViewModel","type":"LogViewModel","description":"日志 ViewModel（消费者）。"}],"variants":[{"label":"基础示例","values":{},"image":"LogBar-0.png","mesh":null}],"error":null,"example":"<controls:LogBar />","group":"信号与状态"},{"name":"ModuleChip","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ModuleChip.xaml.cs","summary":"模块小框：一个圆点（状态）+ 模块名，边框亮灭表示生产 / 维护。顶栏模块行用它，别处要显示模块状态和生产 / 维护也用它","is3D":false,"project":false,"properties":[{"name":"Text","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ModuleChip","description":"框里的字（模块名，machine.xml 原样）","enumValues":[]},{"name":"Tone","type":"ModuleStateTone","default":"Inactive","readOnly":false,"twoWay":false,"owner":"ModuleChip","description":"状态色调：就绪圆点绿、报警红，其他灰","enumValues":["Inactive","Busy","Ready","Warning","Alarm"]},{"name":"IsProduction","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"ModuleChip","description":"生产模式：边框亮；维护（或不知道）边框灭","enumValues":[]},{"name":"HasMode","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"ModuleChip","description":"分不分生产 / 维护：不分的（供液）不画边框","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"ModuleChip-0.png","mesh":null},{"label":"维护模式","values":{"IsProduction":"false"},"image":"ModuleChip-1.png","mesh":null},{"label":"不区分生产维护","values":{"HasMode":"false"},"image":"ModuleChip-2.png","mesh":null}],"error":null,"example":"<controls:ModuleChip\n    Text=\"Chamber1\"\n    Tone=\"{Binding StateTone}\"\n    IsProduction=\"{Binding IsProduction}\"\n    HasMode=\"True\" />","group":"信号与状态"},{"name":"ModuleStateBadge","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ModuleStateBadge.xaml.cs","summary":"模块状态徽标：状态字 + 按色调上色的整条底色。LoadPort、Robot、腔体……所有模块的状态显示统一用它。 没有状态字（没接状态的地方）整个收起，不留一条空的灰条。","is3D":false,"project":false,"properties":[{"name":"Text","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ModuleStateBadge","description":"状态字（显示模型的 StateText，已按当前语言翻好）；空就不显示。","enumValues":[]},{"name":"Tone","type":"ModuleStateTone","default":"Inactive","readOnly":false,"twoWay":false,"owner":"ModuleStateBadge","description":"色调（显示模型的 StateTone）。","enumValues":["Inactive","Busy","Ready","Warning","Alarm"]},{"name":"IsCompact","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"ModuleStateBadge","description":"缩小版：小卡片标题行里用，矮一截、字小、宽度随字。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"ModuleStateBadge-0.png","mesh":null},{"label":"紧凑模式","values":{"IsCompact":"true"},"image":"ModuleStateBadge-1.png","mesh":null}],"error":null,"example":"<controls:ModuleStateBadge\n    Text=\"{Binding StateText}\"\n    Tone=\"{Binding StateTone}\"\n    IsCompact=\"False\" />","group":"信号与状态"},{"name":"ModuleStatusBar","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ModuleStatusBar.xaml.cs","summary":"顶栏模块行：切哪一页都看得到各模块的状态和 Auto / Manual。控件自带 ViewModel","is3D":false,"project":false,"properties":[],"members":[{"name":"ViewModel","type":"ModuleStatusBarViewModel","description":"模块行 ViewModel"}],"variants":[{"label":"基础示例","values":{},"image":"ModuleStatusBar-0.png","mesh":null}],"error":null,"example":"<controls:ModuleStatusBar />","group":"信号与状态"},{"name":"ProgressOverlay","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ProgressOverlay.xaml.cs","summary":"进度弹框（查询、导出……都用它）：盖住整页、中间一个圆环，开关、进度、取消绑 VM 上的 ProgressState","is3D":false,"project":false,"properties":[{"name":"State","type":"ProgressState","default":"null","readOnly":false,"twoWay":false,"owner":"ProgressOverlay","description":"绑 VM 上的 ProgressState：开没开、进度、取消都从它来","enumValues":[]},{"name":"Text","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"ProgressOverlay","description":"圆环下面那行字（页面上绑语言包，如 {DynamicResource datachart.exporting}）","enumValues":[]},{"name":"IsIndeterminate","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"ProgressOverlay","description":"不知道进度（查询）：圆环一直转，中间不写百分比","enumValues":[]},{"name":"ShowDelay","type":"Int32","default":"500","readOnly":false,"twoWay":false,"owner":"ProgressOverlay","description":"开始以后过多少毫秒还没完才弹出来（默认 500）：放大、拖动时的快查询不闪","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"ProgressOverlay-0.png","mesh":null}],"error":null,"example":"<controls:ProgressOverlay\n    State=\"{Binding Progress}\"\n    Text=\"正在加载\"\n    IsIndeterminate=\"True\" />","group":"信号与状态"},{"name":"Robot","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/Robot.xaml.cs","summary":"原二维机械手外观；绑定入口与运动行为沿用 RobotViewBase。","is3D":false,"project":false,"properties":[{"name":"ArmType","type":"RobotArmType","default":"Linear","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"机械手结构枚举；选择直伸或蛙式，运动姿态仍从各手臂数据给入。","enumValues":["Linear","FrogLeg"]},{"name":"Rotation","type":"RobotDirection","default":"North","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"转台目标朝向（俯视，屏幕上方为北）：North 0°、East 90°、South 180°、West 270°，只接受这四个方向；按最短路径转过去。","enumValues":["North","East","South","West"]},{"name":"Travel","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"水平平移目标：机械手中心相对控件中心向右移多少，负数向左；机械手可以移出控件范围。 按机械手设计尺寸 400×400 计，跟机械手一起按短边等比缩放：短边 400 时就是像素，短边 800 时实际移动 2 倍。","enumValues":[]},{"name":"ExtendedReach","type":"Double","default":"150","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"伸出行程：手臂完全伸出（Extension = 1）时片心离转台中心多远，按机械手设计尺寸 400×400 计，跟机械手一起等比缩放。 各机台按自己的臂展配；形状不变，只是伸得远近不同。收回到底固定为 24。","enumValues":[]},{"name":"ArmCount","type":"Int32","default":"2","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"手指（手臂）数量，1~4：控件画出 1..ArmCount 号手臂，Arms 里没有数据的手臂按空手收回显示。","enumValues":[]},{"name":"Arms","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"手臂数据（RobotArmModel），按 Arm 号对应 1..ArmCount：超出 ArmCount 的忽略，同号取第一个； 集合增删与每只手臂的属性变化都会刷新。","enumValues":[]},{"name":"IsAnimationEnabled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"是否播放运动动画；false 时姿态直接跳到目标（设计器、截图用）。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"Robot-0.png","mesh":null},{"label":"朝东（90°）","values":{"Rotation":"East"},"image":"Robot-1.png","mesh":null},{"label":"蛙式机械手","values":{"ArmType":"FrogLeg"},"image":"Robot-2.png","mesh":null}],"error":null,"example":"<controls:Robot\n    ArmType=\"Linear\"\n    Arms=\"{Binding Arms}\"\n    Rotation=\"{Binding Rotation}\"\n    Travel=\"{Binding Travel}\"\n    IsAnimationEnabled=\"True\" />","group":"数据与设备卡片"},{"name":"Robot3D","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/Robot3D.xaml.cs","summary":"可像二维 Robot 一样直接声明和绑定的三维机械手。直伸式、蛙式共用原动作轨道和手臂模型； 自带相机、灯光、旋转和缩放，继承页面 DataContext，不连接服务或发设备指令。","is3D":true,"project":false,"properties":[{"name":"ShowViewToolbar","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"Robot3D","description":"是否显示视角按钮；不改变设备状态。","enumValues":[]},{"name":"ArmType","type":"RobotArmType","default":"Linear","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"机械手结构枚举；选择直伸或蛙式，运动姿态仍从各手臂数据给入。","enumValues":["Linear","FrogLeg"]},{"name":"Rotation","type":"RobotDirection","default":"North","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"转台目标朝向（俯视，屏幕上方为北）：North 0°、East 90°、South 180°、West 270°，只接受这四个方向；按最短路径转过去。","enumValues":["North","East","South","West"]},{"name":"Travel","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"水平平移目标：机械手中心相对控件中心向右移多少，负数向左；机械手可以移出控件范围。 按机械手设计尺寸 400×400 计，跟机械手一起按短边等比缩放：短边 400 时就是像素，短边 800 时实际移动 2 倍。","enumValues":[]},{"name":"ExtendedReach","type":"Double","default":"150","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"伸出行程：手臂完全伸出（Extension = 1）时片心离转台中心多远，按机械手设计尺寸 400×400 计，跟机械手一起等比缩放。 各机台按自己的臂展配；形状不变，只是伸得远近不同。收回到底固定为 24。","enumValues":[]},{"name":"ArmCount","type":"Int32","default":"2","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"手指（手臂）数量，1~4：控件画出 1..ArmCount 号手臂，Arms 里没有数据的手臂按空手收回显示。","enumValues":[]},{"name":"Arms","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"手臂数据（RobotArmModel），按 Arm 号对应 1..ArmCount：超出 ArmCount 的忽略，同号取第一个； 集合增删与每只手臂的属性变化都会刷新。","enumValues":[]},{"name":"IsAnimationEnabled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"RobotViewBase","description":"是否播放运动动画；false 时姿态直接跳到目标（设计器、截图用）。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"Robot3D-0.png","mesh":"Robot3D-0.mesh.js"},{"label":"朝东（90°）","values":{"Rotation":"East"},"image":"Robot3D-1.png","mesh":"Robot3D-1.mesh.js"},{"label":"蛙式机械手","values":{"ArmType":"FrogLeg"},"image":"Robot3D-2.png","mesh":"Robot3D-2.mesh.js"}],"error":null,"example":"<controls:Robot3D\n    Arms=\"{Binding Arms}\"\n    Rotation=\"{Binding Rotation}\"\n    Travel=\"{Binding Travel}\"\n    ShowViewToolbar=\"True\" />","group":"3D 组合视图"},{"name":"SampleUserControl","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/SampleUserControl.xaml.cs","summary":"","is3D":false,"project":false,"properties":[],"members":[],"variants":[{"label":"基础示例","values":{},"image":"SampleUserControl-0.png","mesh":null}],"error":null,"example":"<controls:SampleUserControl />","group":"数据与设备卡片"},{"name":"StationCard","namespace":"xyz.Client.Presentation.Controls","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/StationCard.xaml.cs","summary":"调度图上的一个站点卡片（DataContext = RobotStationModel）：按站点类型选卡片——LoadPort 用 LoadPortInfoCard（花篮）， 腔体和其他站点用 ChamberInfoCard（单片）。卡片按真实字号排版、随给定宽高伸缩。","is3D":false,"project":false,"properties":[{"name":"DiskSize","type":"Double","default":"100","readOnly":false,"twoWay":false,"owner":"StationCard","description":"卡片上圆片的直径：跟调度图里机械手叉上的片一样大，由调度图按机械手的显示尺寸给。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"StationCard-0.png","mesh":null}],"error":null,"example":"<controls:StationCard\n    DataContext=\"{Binding Station}\"\n    DiskSize=\"100\" />","group":"数据与设备卡片"},{"name":"ArmVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/ArmVisual3D.cs","summary":"可组合的摆臂外观：局部 Y 轴向上，原点是回转中心，零角度沿 +X。 只显示外部反馈；不包含 Lift、喷嘴、供液管路或任何设备控制逻辑。","is3D":true,"project":false,"properties":[{"name":"Angle","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"ArmVisual3D","description":"当前摆角，单位为度。正角度使臂尖从 +X 转向 -Z。","enumValues":[]},{"name":"Length","type":"Double","default":"2.2","readOnly":false,"twoWay":false,"owner":"ArmVisual3D","description":"回转中心到末端安装块中心的距离，与场景使用同一长度单位。","enumValues":[]},{"name":"Width","type":"Double","default":"0.23","readOnly":false,"twoWay":false,"owner":"ArmVisual3D","description":"控制外观尺寸；三维件使用场景示意单位，不能当成设备毫米值或运动指令。","enumValues":[]},{"name":"Thickness","type":"Double","default":"0.085","readOnly":false,"twoWay":false,"owner":"ArmVisual3D","description":"控制外观尺寸；三维件使用场景示意单位，不能当成设备毫米值或运动指令。","enumValues":[]},{"name":"PivotRadius","type":"Double","default":"0.285","readOnly":false,"twoWay":false,"owner":"ArmVisual3D","description":"控制外观尺寸；三维件使用场景示意单位，不能当成设备毫米值或运动指令。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[{"name":"Attachments","type":"Visual3DCollection","description":"随摆角和外部安装变换一起运动的附件，如 DIW/SC1 管路；附件动作状态独立。"}],"variants":[{"label":"基础示例","values":{},"image":"ArmVisual3D-0.png","mesh":"ArmVisual3D-0.mesh.js"},{"label":"Angle = 45°","values":{"Angle":"45"},"image":"ArmVisual3D-1.png","mesh":"ArmVisual3D-1.mesh.js"},{"label":"Angle = 90°","values":{"Angle":"90"},"image":"ArmVisual3D-2.png","mesh":"ArmVisual3D-2.mesh.js"},{"label":"加长至 3.2","values":{"Length":"3.2"},"image":"ArmVisual3D-3.png","mesh":"ArmVisual3D-3.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"ArmVisual3D-4.png","mesh":"ArmVisual3D-4.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"ArmVisual3D-5.png","mesh":"ArmVisual3D-5.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:ArmVisual3D\n            Angle=\"{Binding DataContext.ArmAngle, ElementName=Scene}\"\n            Length=\"2.2\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"BowlVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/BowlVisual3D.cs","summary":"薄壁 Bowl 外观。HeightLevel 选择三级侧壁高度，IsRaised 控制升降：底边一直贴着安装面， 升起时只把上沿抬高、直侧壁跟着拉长，侧壁始终连到底，不会悬空露缝。 IsUnknown=true（命令发了、到位信号还没亮）上沿停在行程中间、整个 Bowl 画成红色。 原点为底面中心，Y 向上；不包含晶圆、主轴和设备指令。","is3D":true,"project":false,"properties":[{"name":"HeightLevel","type":"Int32","default":"1","readOnly":false,"twoWay":false,"owner":"BowlVisual3D","description":"外观高度等级：1 为原有低矮造型，2、3 依次加高；不是升降挡位。","enumValues":[]},{"name":"Radius","type":"Double","default":"1.59","readOnly":false,"twoWay":false,"owner":"BowlVisual3D","description":"外半径，与装配使用同一长度单位；内径随半径保持薄壁比例。","enumValues":[]},{"name":"IsRaised","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"BowlVisual3D","description":"升降反馈，true 上位、false 下位；底边保持在安装面，不改变 HeightLevel。","enumValues":[]},{"name":"IsUnknown","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"BowlVisual3D","description":"位置未知：上沿画到行程中间、整个 Bowl 变红，到位（变回 false）后红色撤掉、再走到 IsRaised 那一头。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"BowlVisual3D-0.png","mesh":"BowlVisual3D-0.mesh.js"},{"label":"升到位","values":{"IsRaised":"true"},"image":"BowlVisual3D-1.png","mesh":"BowlVisual3D-1.mesh.js"},{"label":"位置未知","values":{"IsUnknown":"true"},"image":"BowlVisual3D-2.png","mesh":"BowlVisual3D-2.mesh.js"},{"label":"外观高度 2","values":{"HeightLevel":"2"},"image":"BowlVisual3D-3.png","mesh":"BowlVisual3D-3.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"BowlVisual3D-4.png","mesh":"BowlVisual3D-4.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"BowlVisual3D-5.png","mesh":"BowlVisual3D-5.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:BowlVisual3D\n            IsRaised=\"{Binding DataContext.BowlRaised, ElementName=Scene}\"\n            IsUnknown=\"{Binding DataContext.BowlUnknown, ElementName=Scene}\"\n            HeightLevel=\"1\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"LiftVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/LiftVisual3D.cs","summary":"两态升降气缸外观：IsRaised=true 升起，false 收回；IsUnknown=true（命令发了、到位信号还没亮）停在行程中间、整个气缸画成红色。 原点在底座底面中心，沿 +Y 伸出；尺寸、行程和过渡时间均为内部示意参数。","is3D":true,"project":false,"properties":[{"name":"IsRaised","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LiftVisual3D","description":"绑定外部气缸状态：true 为上位，false 为下位。变化时自动播放升降过渡。","enumValues":[]},{"name":"IsUnknown","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LiftVisual3D","description":"位置未知：画到行程中间、整个气缸变红，到位（变回 false）后红色撤掉、再走到 IsRaised 那一头。","enumValues":[]},{"name":"MountHeight","type":"Double","default":"0","readOnly":true,"twoWay":false,"owner":"LiftVisual3D","description":"安装面当前的局部 Y 坐标（含动画），用于组装；不包含外部 Transform。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"LiftVisual3D-0.png","mesh":"LiftVisual3D-0.mesh.js"},{"label":"升到位","values":{"IsRaised":"true"},"image":"LiftVisual3D-1.png","mesh":"LiftVisual3D-1.mesh.js"},{"label":"位置未知","values":{"IsUnknown":"true"},"image":"LiftVisual3D-2.png","mesh":"LiftVisual3D-2.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"LiftVisual3D-3.png","mesh":"LiftVisual3D-3.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"LiftVisual3D-4.png","mesh":"LiftVisual3D-4.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:LiftVisual3D\n            IsRaised=\"{Binding DataContext.LiftRaised, ElementName=Scene}\"\n            IsUnknown=\"{Binding DataContext.LiftUnknown, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"TankVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/TankVisual3D.cs","summary":"供液槽三维外观：透明圆筒 + 里面的液体，原点在罐底中心、Y 向上","is3D":true,"project":false,"properties":[{"name":"FillFraction","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"TankVisual3D","description":"液面高度占罐高的比例（0～1），0 不画液体","enumValues":[]},{"name":"IsAlarm","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"TankVisual3D","description":"液体画成报警红","enumValues":[]},{"name":"WallTransparency","type":"Double","default":"0.72","readOnly":false,"twoWay":false,"owner":"TankVisual3D","description":"罐壁透明度（0～1）","enumValues":[]},{"name":"Azimuth","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"TankVisual3D","description":"相机的方位角（度），用来分前后两半罐壁","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"TankVisual3D-0.png","mesh":"TankVisual3D-0.mesh.js"},{"label":"液面 25%（示例输入）","values":{"FillFraction":"0.25"},"image":"TankVisual3D-1.png","mesh":"TankVisual3D-1.mesh.js"},{"label":"液面 80%（示例输入）","values":{"FillFraction":"0.8"},"image":"TankVisual3D-2.png","mesh":"TankVisual3D-2.mesh.js"},{"label":"报警液面","values":{"IsAlarm":"true"},"image":"TankVisual3D-3.png","mesh":"TankVisual3D-3.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"TankVisual3D-4.png","mesh":"TankVisual3D-4.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"TankVisual3D-5.png","mesh":"TankVisual3D-5.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:TankVisual3D\n            FillFraction=\"{Binding DataContext.DisplayFillFraction, ElementName=Scene}\"\n            IsAlarm=\"{Binding DataContext.TankAlarm, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"FluidRouteVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/FluidRouteVisual3D.cs","summary":"按路径绘制的透明空心管路，可用于腔体、Tank 和 CDS。 外部通过依赖属性提供路径、外观和流动状态，控件只负责显示。","is3D":true,"project":false,"properties":[{"name":"Path","type":"Point3DCollection","default":"null","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"管中心的路径点，使用场景统一长度单位。替换集合或修改集合中的点都会重画管路。","enumValues":[]},{"name":"PipeRadius","type":"Double","default":"0.06","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"管外半径，必须大于 0。","enumValues":[]},{"name":"WallThickness","type":"Double","default":"0.012","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"管壁厚度。实际厚度最多取外半径的 90%，始终保留空腔。","enumValues":[]},{"name":"FluidCoreRatio","type":"Double","default":"0.58","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"液芯半径与内腔半径的比值，范围为 (0, 1]。用于留出透明间隙，不表示真实充液率。","enumValues":[]},{"name":"BendRadius","type":"Double","default":"0.22","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"弯头圆角半径。短管段会自动缩小圆角，0 表示保留折线。","enumValues":[]},{"name":"WallOpacity","type":"Double","default":"0.18","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"管壁不透明度强度，范围为 [0, 1]，默认 0.18。内外壁按比例使用此值，0 时隐藏管壁。","enumValues":[]},{"name":"WallColor","type":"Color","default":"#FFB4B4B4","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"透明管壁的颜色，默认使用中性灰。","enumValues":[]},{"name":"FluidColor","type":"Color","default":"#FFC4C4C4","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"液体底色。液芯颜色由 FlowColor 和此颜色按 3:1 混合。","enumValues":[]},{"name":"FlowColor","type":"Color","default":"#FF52D4EF","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"水流主色，同时用于液芯着色和移动水纹，默认青蓝色。","enumValues":[]},{"name":"IsFilled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"管内是否有液体。只有 IsFilled 和 IsFlowing 都为 true 时显示液芯。","enumValues":[]},{"name":"IsFlowing","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"是否正在流动。false 时移除液芯和水纹，只显示透明管壁；不修改 IsFilled。","enumValues":[]},{"name":"FlowSpeed","type":"Double","default":"0.55","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"动画速度，单位为场景长度/秒。0 表示暂停水纹；只是显示参数，不代表实测流量。","enumValues":[]},{"name":"ReverseFlow","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"是否反向流动。默认从 Path 的第一个点流向最后一个点。","enumValues":[]},{"name":"IsAnimationEnabled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"FluidRouteVisual3D","description":"是否播放动画。false 时冻结水纹，保留当前液芯和流动状态。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"FluidRouteVisual3D-0.png","mesh":"FluidRouteVisual3D-0.mesh.js"},{"label":"出液显示","values":{"IsFlowing":"true"},"image":"FluidRouteVisual3D-1.png","mesh":"FluidRouteVisual3D-1.mesh.js"},{"label":"关闭动画","values":{"IsAnimationEnabled":"false"},"image":"FluidRouteVisual3D-2.png","mesh":"FluidRouteVisual3D-2.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"FluidRouteVisual3D-3.png","mesh":"FluidRouteVisual3D-3.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"FluidRouteVisual3D-4.png","mesh":"FluidRouteVisual3D-4.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:FluidRouteVisual3D\n            Path=\"{Binding DataContext.Route3D, ElementName=Scene}\"\n            PipeRadius=\"0.08\"\n            WallThickness=\"0.016\"\n            BendRadius=\"0.18\"\n            IsFlowing=\"{Binding DataContext.IsFlowing, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"BufferVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/BufferVisual3D.cs","summary":"可放进共享 Viewport3D 的贯通缓存架。前后对称，仅显示槽位和晶圆，不包含相机、灯光或模块状态。 三维对象不继承 DataContext，绑定数据时显式指定 Source 或 ElementName。","is3D":true,"project":false,"properties":[{"name":"FirstSlot","type":"Int32","default":"1","readOnly":false,"twoWay":false,"owner":"BufferVisual3D","description":"最底层的物理槽号，默认 1。","enumValues":[]},{"name":"SlotCount","type":"Int32","default":"10","readOnly":false,"twoWay":false,"owner":"BufferVisual3D","description":"实际槽数，默认 10；0 清空结构和晶圆。固定紧凑槽距。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"BufferVisual3D","description":"按 WaferModel.Slot 摆片、State 上色。跟踪集合和单片槽位变化；在 UI 线程更新。","enumValues":[]},{"name":"WaferCount","type":"Int32","default":"0","readOnly":true,"twoWay":false,"owner":"BufferVisual3D","description":"当前有效占用槽数，只读。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"BufferVisual3D-0.png","mesh":"BufferVisual3D-0.mesh.js"},{"label":"8 个槽（示例）","values":{"SlotCount":"8"},"image":"BufferVisual3D-1.png","mesh":"BufferVisual3D-1.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"BufferVisual3D-2.png","mesh":"BufferVisual3D-2.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"BufferVisual3D-3.png","mesh":"BufferVisual3D-3.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:BufferVisual3D\n            FirstSlot=\"1\"\n            SlotCount=\"{Binding DataContext.SlotCount, ElementName=Scene}\"\n            Wafers=\"{Binding DataContext.Wafers, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"CarrierVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/CarrierVisual3D.cs","summary":"载具（花篮）三维外观：底板、两侧带槽齿的侧壁、前后立柱、顶梁和提手，前立柱上标槽号（1、5、10……）； 有片的槽各放一片 DiskVisual3D（跟腔体的旋转盘同一个组件，盘面状态色、片号都沿用）。 槽数照 machine.xml 配（SlotCount），槽距不变、槽数多花篮就高。 开口朝 +Z（操作员那面）露出晶圆，背面朝 -Z 对着 LoadPort 背板。原点在底面中心，Y 向上； 放进 LoadPortVisual3D.Attachments 就坐在托板的定位销上、跟着对接前后走。只显示，点了哪片由装配层用 SlotOf 认。","is3D":true,"project":false,"properties":[{"name":"SlotCount","type":"Int32","default":"0","readOnly":false,"twoWay":false,"owner":"CarrierVisual3D","description":"槽数（machine.xml 里 LoadPort 的 SlotCount），花篮高度、槽齿、槽号都跟着它；0 = 还不知道，什么都不画。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"CarrierVisual3D","description":"花篮里的片（WaferModel，按 Slot 放进槽里，交给 DiskVisual3D 按 State 上色）；整个换掉才刷新。","enumValues":[]},{"name":"SelectedSlot","type":"Int32","default":"0","readOnly":false,"twoWay":false,"owner":"CarrierVisual3D","description":"选中的槽（点了哪片），0 = 没选；那一片高亮。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF484848","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[{"name":"OccupiedSlots","type":"IReadOnlyList<int>","description":"有片的槽号（从小到大）。"}],"variants":[{"label":"基础示例","values":{},"image":"CarrierVisual3D-0.png","mesh":"CarrierVisual3D-0.mesh.js"},{"label":"8 个槽（示例）","values":{"SlotCount":"8"},"image":"CarrierVisual3D-1.png","mesh":"CarrierVisual3D-1.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"CarrierVisual3D-2.png","mesh":"CarrierVisual3D-2.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"CarrierVisual3D-3.png","mesh":"CarrierVisual3D-3.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:CarrierVisual3D\n            SlotCount=\"{Binding DataContext.SlotCount, ElementName=Scene}\"\n            Wafers=\"{Binding DataContext.Wafers, ElementName=Scene}\"\n            SelectedSlot=\"{Binding DataContext.SelectedSlot, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"ChamberBaseVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/ChamberBaseVisual3D.cs","summary":"深灰色切角安装底板。原点在上表面中心，Y 向上，板厚向下延伸。 Attachments 内的硬件共享底座的外部变换，设备状态互相独立。","is3D":true,"project":false,"properties":[{"name":"Length","type":"Double","default":"5.6","readOnly":false,"twoWay":false,"owner":"ChamberBaseVisual3D","description":"底板沿 X 轴的长度。","enumValues":[]},{"name":"Width","type":"Double","default":"4.4","readOnly":false,"twoWay":false,"owner":"ChamberBaseVisual3D","description":"底板沿 Z 轴的宽度。","enumValues":[]},{"name":"Thickness","type":"Double","default":"0.12","readOnly":false,"twoWay":false,"owner":"ChamberBaseVisual3D","description":"板厚向 -Y 延伸；调整厚度不会顶起或移动上方硬件。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF333333","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[{"name":"Attachments","type":"Visual3DCollection","description":"安装硬件的集合；各子项 Transform 相对于底板上表面中心。"}],"variants":[{"label":"基础示例","values":{},"image":"ChamberBaseVisual3D-0.png","mesh":"ChamberBaseVisual3D-0.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"ChamberBaseVisual3D-1.png","mesh":"ChamberBaseVisual3D-1.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"ChamberBaseVisual3D-2.png","mesh":"ChamberBaseVisual3D-2.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:ChamberBaseVisual3D\n            Length=\"6.4\"\n            Width=\"4.2\"\n            Thickness=\"0.12\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"DiskVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/DiskVisual3D.cs","summary":"Wafer/Disk 的三维版本。复用独立 Wafer 实例的盘面和状态色，原二维控件不变；腔体的旋转盘、LoadPort 花篮里的片都用它。 局部 Y 向上，底面中心为原点。旋转速度沿用二维控件的度/秒语义（大于 1 时旋转）。","is3D":true,"project":false,"properties":[{"name":"Data","type":"Object","default":"null","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"控件要显示的数据对象；晶圆控件通常接收 WaferModel。","enumValues":[]},{"name":"IsDiskVisible","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"没有晶圆数据时是否仍显示圆盘；有 Data 时按晶圆业务状态显示。","enumValues":[]},{"name":"FillColor","type":"Brush","default":"#FF808080","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"圆盘填充画刷；有匹配的晶圆业务状态时优先使用状态色。","enumValues":[]},{"name":"BorderBrush","type":"Brush","default":"#FF808080","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"圆盘边线的画刷；三维盘沿用二维的逻辑外观参数。","enumValues":[]},{"name":"BorderThickness","type":"Thickness","default":"1,1,1,1","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"圆盘边线厚度，Thickness 类型；不是三维盘实体的 Thickness。","enumValues":[]},{"name":"Label","type":"String","default":"空字符串","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"圆片文字覆盖值；三维 Disk 支持覆盖，二维 Wafer 当前模板仍显示 Data.LpSlot。","enumValues":[]},{"name":"RotationSpeed","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"显示旋转速度（度/秒），不能把设备 RPM 不经换算直接绑定。","enumValues":[]},{"name":"RotateClockwise","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"从上方观察时的旋转方向，true 为顺时针；RotationSpeed 仍使用度/秒。","enumValues":[]},{"name":"Radius","type":"Double","default":"1.32","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"控制外观尺寸；三维件使用场景示意单位，不能当成设备毫米值或运动指令。","enumValues":[]},{"name":"Thickness","type":"Double","default":"0.045","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"控制外观尺寸；三维件使用场景示意单位，不能当成设备毫米值或运动指令。","enumValues":[]},{"name":"SpindleHeight","type":"Double","default":"0","readOnly":false,"twoWay":false,"owner":"DiskVisual3D","description":"盘下面主轴（旋转电机）露出来的长度：盘架高了就用一根轴撑到安装面上，免得悬空；0 = 不画主轴（默认）。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"DiskVisual3D-0.png","mesh":"DiskVisual3D-0.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"DiskVisual3D-1.png","mesh":"DiskVisual3D-1.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"DiskVisual3D-2.png","mesh":"DiskVisual3D-2.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:DiskVisual3D\n            Data=\"{Binding DataContext.Wafer, ElementName=Scene}\"\n            IsDiskVisible=\"True\"\n            Radius=\"1.32\"\n            Thickness=\"0.045\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"DoorVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/DoorVisual3D.cs","summary":"气缸驱动的上下升降门示意。上升打开、下降关闭，外部绑定 IsOpen；IsUnknown=true（命令发了、到位信号还没亮）门板停在行程中间、整个门画成红色。 原点为门框下方安装面中心，Y 向上，门宽沿 X；打开时门板完全高于门框。","is3D":true,"project":false,"properties":[{"name":"IsOpen","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"DoorVisual3D","description":"门的开到位反馈；与 IsUnknown 分开提供，未知优先显示中间位置及报警色。","enumValues":[]},{"name":"IsUnknown","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"DoorVisual3D","description":"位置未知：门板画到行程中间、整个门变红，到位（变回 false）后红色撤掉、再走到 IsOpen 那一头。","enumValues":[]},{"name":"Width","type":"Double","default":"2.2","readOnly":false,"twoWay":false,"owner":"DoorVisual3D","description":"门板宽度，使用装配的统一长度单位。","enumValues":[]},{"name":"Height","type":"Double","default":"0.58","readOnly":false,"twoWay":false,"owner":"DoorVisual3D","description":"门板高度；动画行程由内部示意结构决定。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"DoorVisual3D-0.png","mesh":"DoorVisual3D-0.mesh.js"},{"label":"开到位","values":{"IsOpen":"true"},"image":"DoorVisual3D-1.png","mesh":"DoorVisual3D-1.mesh.js"},{"label":"位置未知","values":{"IsUnknown":"true"},"image":"DoorVisual3D-2.png","mesh":"DoorVisual3D-2.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"DoorVisual3D-3.png","mesh":"DoorVisual3D-3.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"DoorVisual3D-4.png","mesh":"DoorVisual3D-4.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:DoorVisual3D\n            IsOpen=\"{Binding DataContext.DoorOpened, ElementName=Scene}\"\n            IsUnknown=\"{Binding DataContext.DoorUnknown, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"FluidPipeVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/FluidPipeVisual3D.cs","summary":"Arm 上的一路喷嘴：透明供液管、向下喷口和外部液柱。 与普通 FluidPipe 控件共用 FluidRouteVisual3D；DIW、SC1 各自绑定 IsFlowing。","is3D":true,"project":false,"properties":[{"name":"IsFlowing","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"本路喷嘴是否出液。关闭时管内液芯、外部液柱和落点波纹全部消失。","enumValues":[]},{"name":"IsAnimationEnabled","type":"Boolean","default":"true","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"暂停动画但保留出液状态。","enumValues":[]},{"name":"Length","type":"Double","default":"2.2","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"沿 Arm 的局部 +X 方向布管，长度与场景使用同一单位。","enumValues":[]},{"name":"StreamLength","type":"Double","default":"0.55","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"喷口到接液面的距离；0 时只有管内水流，不显示外部液柱和波纹。","enumValues":[]},{"name":"FlowColor","type":"Color","default":"#FF52D4EF","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"管内水流、喷口液柱和落点波纹使用同一种颜色。","enumValues":[]},{"name":"WallOpacity","type":"Double","default":"0.18","readOnly":false,"twoWay":false,"owner":"FluidPipeVisual3D","description":"透明供液管的管壁不透明度强度。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"FluidPipeVisual3D-0.png","mesh":"FluidPipeVisual3D-0.mesh.js"},{"label":"出液显示","values":{"IsFlowing":"true"},"image":"FluidPipeVisual3D-1.png","mesh":"FluidPipeVisual3D-1.mesh.js"},{"label":"关闭动画","values":{"IsAnimationEnabled":"false"},"image":"FluidPipeVisual3D-2.png","mesh":"FluidPipeVisual3D-2.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"FluidPipeVisual3D-3.png","mesh":"FluidPipeVisual3D-3.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"FluidPipeVisual3D-4.png","mesh":"FluidPipeVisual3D-4.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:FluidPipeVisual3D\n            Length=\"2.2\"\n            StreamLength=\"0.6\"\n            IsFlowing=\"{Binding DataContext.NozzleOn, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"HomeCupVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/HomeCupVisual3D.cs","summary":"Home 位置的固定接液杯：敞口、收液锥面及贯通的下排液口。 原点在排液口底面中心，Y 向上。放在场景中，不随 Arm 或 Lift 移动。","is3D":true,"project":false,"properties":[{"name":"Radius","type":"Double","default":"0.32","readOnly":false,"twoWay":false,"owner":"HomeCupVisual3D","description":"杯口外半径，与装配使用相同长度单位。","enumValues":[]},{"name":"Height","type":"Double","default":"0.655","readOnly":false,"twoWay":false,"owner":"HomeCupVisual3D","description":"排液口底面到杯口的总高度；杯口局部坐标为 (0, Height, 0)。","enumValues":[]},{"name":"IsDraining","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HomeCupVisual3D","description":"可选的接液/排液状态反馈，true 自动高亮；液流由管子组件显示。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"HomeCupVisual3D-0.png","mesh":"HomeCupVisual3D-0.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"HomeCupVisual3D-1.png","mesh":"HomeCupVisual3D-1.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"HomeCupVisual3D-2.png","mesh":"HomeCupVisual3D-2.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:HomeCupVisual3D\n            Radius=\"0.28\"\n            Height=\"0.35\"\n            IsDraining=\"{Binding DataContext.HomeDraining, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"LoadPortVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/LoadPortVisual3D.cs","summary":"LoadPort 三维外观：背板（门洞、信号灯面板）、背板门、下面的驱动柜、承载台和前后走的托板。 载具（CarrierVisual3D）放进 Attachments，坐在托板的定位销上、跟着对接前后走。 外部只绑结果：IsDocked（托板推进去贴着门洞）、IsDoorOpen / IsDoorUnknown（门开到位 / 在半路）、面板上的灯。 动作有先后：要开门先推进去再开，要退出先关门再退；每个动作全行程 0.5 s（用户定的，写死），中途换目标从当前位置接着走。 只有在动的那一块（门或托板）高亮；门在半路停在行程中间、一直高亮。原点在承载台面中心，Y 向上，+Z 朝操作员，背板在 -Z。","is3D":true,"project":false,"properties":[{"name":"IsDocked","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"托板推进去了（对接）：载具贴着门洞。false = 退出来，人可以放取载具。","enumValues":[]},{"name":"IsDoorOpen","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"门开到位（只在对接时才画得开：没推进去门一定是关着的）。","enumValues":[]},{"name":"IsDoorUnknown","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"门在半路（开到位、关到位都没亮）：门画在行程中间并一直高亮，到位了再走到那一头。","enumValues":[]},{"name":"IsPresent","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"面板上\"在位\"灯。","enumValues":[]},{"name":"IsPlaced","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"面板上\"放置到位\"灯。","enumValues":[]},{"name":"IsAutoMode","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortVisual3D","description":"存取方式：true 亮 AUTO（绿），false 亮 MANUAL（黄）。","enumValues":[]},{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[{"name":"Attachments","type":"Visual3DCollection","description":"装在托板上的东西（载具）；原点在托板定位销上，跟着对接前后走。"}],"variants":[{"label":"基础示例","values":{},"image":"LoadPortVisual3D-0.png","mesh":"LoadPortVisual3D-0.mesh.js"},{"label":"已对接","values":{"IsDocked":"true"},"image":"LoadPortVisual3D-1.png","mesh":"LoadPortVisual3D-1.mesh.js"},{"label":"门打开","values":{"IsDoorOpen":"true"},"image":"LoadPortVisual3D-2.png","mesh":"LoadPortVisual3D-2.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"LoadPortVisual3D-3.png","mesh":"LoadPortVisual3D-3.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"LoadPortVisual3D-4.png","mesh":"LoadPortVisual3D-4.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:LoadPortVisual3D\n            IsDocked=\"{Binding DataContext.Docked, ElementName=Scene}\"\n            IsDoorOpen=\"{Binding DataContext.DoorOpen, ElementName=Scene}\"\n            IsDoorUnknown=\"{Binding DataContext.DoorUnknown, ElementName=Scene}\" />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"RobotVisual3D","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/RobotVisual3D.cs","summary":"搬运机械手三维外观。使用原 RobotViewBase.ArmVisual 的每帧几何和原 XAML 手叉轮廓，晶圆直接使用 DiskVisual3D。 不计算运动顺序、不订阅设备、不创建相机；可放入共享 Viewport3D。","is3D":true,"project":false,"properties":[{"name":"IsMoving","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备动作反馈；为 true 时自动高亮，不依赖鼠标选中。","enumValues":[]},{"name":"IsError","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"绑定设备故障反馈（如轴驱动器报错）；为 true 时整块画成报警色，盖过高亮。","enumValues":[]},{"name":"IsSelected","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"由外部选择逻辑设置，与 IsMoving 相互独立。","enumValues":[]},{"name":"BodyColor","type":"Color","default":"#FF686868","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightColor","type":"Color","default":"#FF42A5F5","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"外观颜色；Color 类型用颜色值，Brush 类型用画刷，两者不能直接互换。","enumValues":[]},{"name":"HighlightStrength","type":"Double","default":"0.42","readOnly":false,"twoWay":false,"owner":"HardwareVisual3D","description":"主题色混入比例（0～1），保留金属灰的明暗层次。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"RobotVisual3D-0.png","mesh":"RobotVisual3D-0.mesh.js"},{"label":"选中高亮","values":{"IsSelected":"true"},"image":"RobotVisual3D-1.png","mesh":"RobotVisual3D-1.mesh.js"},{"label":"故障显示","values":{"IsError":"true"},"image":"RobotVisual3D-2.png","mesh":"RobotVisual3D-2.mesh.js"}],"error":null,"example":"<Grid x:Name=\"Scene\">\n    <!-- Visual3D 不继承 DataContext，使用 ElementName 明确绑定来源。 -->\n    <Viewport3D>\n        <Viewport3D.Camera>\n            <OrthographicCamera Position=\"-7,5,9\" LookDirection=\"7,-5,-9\"\n                                UpDirection=\"0,1,0\" Width=\"8\" />\n        </Viewport3D.Camera>\n        <ModelVisual3D>\n            <ModelVisual3D.Content>\n                <AmbientLight Color=\"#A0A0A0\" />\n            </ModelVisual3D.Content>\n        </ModelVisual3D>\n        <hardware:RobotVisual3D />\n    </Viewport3D>\n</Grid>","group":"3D 组件"},{"name":"ChamberScene","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/ChamberScene.xaml.cs","summary":"腔体三维图：底座上装 Bowl、旋转盘、腔门和每条摆臂（Lift 立柱、摆臂、喷嘴管、Home 接液杯）。 装哪些设备看 Devices（后端按 machine.xml 推来的设备组成），状态全部绑定显示模型；盘上的片绑 Wafer（晶圆账）。 摆臂收到新位置后 0.2 s 过渡过去。门、Bowl、Lift 跟到位反馈走：到位画在那一头，未知（命令发了、到位信号还没亮）画在行程中间、整块变红； 摆臂、旋转盘跟轴推送的驱动器报错（IsError）走，报错整块变红。 不注册逐帧事件：液柱长度只在摆臂角度、Lift 高度或出液变化时重算，只有动画进行中角度和高度才会逐帧变，停下来就一点不算。 左键拖动旋转视角、滚轮缩放，图下面一条工具栏：默认视角、俯视。","is3D":true,"project":false,"properties":[{"name":"Devices","type":"ChamberDeviceDataModel","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberScene","description":"设备显示模型（门、Bowl、旋转电机、摆臂）；组成变了（Revision）重搭三维图。","enumValues":[]},{"name":"Wafer","type":"Object","default":"null","readOnly":false,"twoWay":false,"owner":"ChamberScene","description":"盘上的片（晶圆账，WaferModel）；null 显示空盘。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"ChamberScene-0.png","mesh":"ChamberScene-0.mesh.js"}],"error":null,"example":"<hardware:ChamberScene\n    Devices=\"{Binding Devices}\"\n    Wafer=\"{Binding Wafer}\" />","group":"3D 组合视图"},{"name":"LoadPortScene","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/LoadPortScene.xaml.cs","summary":"LoadPort 三维图：LoadPort（LoadPortVisual3D）托板上装一个载具（CarrierVisual3D），在位、到位两盏灯都亮才装上。 状态都从依赖属性进来、原样转给两个组件：对接、门开 / 门在半路、面板上的灯，槽数和片（晶圆账）。 左键拖动旋转视角、滚轮缩放、点一下晶圆选中看槽位；图下面一条工具栏：默认视角、俯视、背面。 右上角写片数，框外一行写选中的槽位和空槽。","is3D":true,"project":false,"properties":[{"name":"IsDocked","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"托板推进去了（对接）。","enumValues":[]},{"name":"IsDoorOpen","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"门开到位。","enumValues":[]},{"name":"IsDoorUnknown","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"门在半路（开到位、关到位都没亮）。","enumValues":[]},{"name":"IsPresent","type":"Boolean?","default":"null","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"在位反馈；null = 反馈不可用，灯灭。跟到位一起定装不装花篮。","enumValues":[]},{"name":"IsPlaced","type":"Boolean?","default":"null","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"放置到位反馈；null = 反馈不可用，灯灭。跟在位一起定装不装花篮。","enumValues":[]},{"name":"IsAutoMode","type":"Boolean","default":"false","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"存取方式 Auto（AUTO 灯亮）/ Manual（MANUAL 灯亮）。","enumValues":[]},{"name":"SlotCount","type":"Int32","default":"0","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"槽数（machine.xml 的 SlotCount）：花篮高度、槽号、片数、空槽都按它；0 = 还不知道，不装花篮。","enumValues":[]},{"name":"Wafers","type":"IEnumerable","default":"null","readOnly":false,"twoWay":false,"owner":"LoadPortScene","description":"花篮里的片（晶圆账，WaferModel 按 Slot 摆、按 State 上色）。","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"LoadPortScene-0.png","mesh":"LoadPortScene-0.mesh.js"},{"label":"已对接","values":{"IsDocked":"true"},"image":"LoadPortScene-1.png","mesh":"LoadPortScene-1.mesh.js"},{"label":"门打开","values":{"IsDoorOpen":"true"},"image":"LoadPortScene-2.png","mesh":"LoadPortScene-2.mesh.js"}],"error":null,"example":"<hardware:LoadPortScene\n    SlotCount=\"{Binding SlotCount}\"\n    Wafers=\"{Binding Wafers}\"\n    IsPresent=\"{Binding Present}\"\n    IsPlaced=\"{Binding Placed}\"\n    IsDocked=\"{Binding Docked}\"\n    IsDoorOpen=\"{Binding DoorOpen}\" />","group":"3D 组合视图"},{"name":"TankScene","namespace":"xyz.Client.Presentation.Controls.ThreeD","source":"xyz.Core/Client/Common/xyz.Client.Presentation/Controls/ThreeD/TankScene.xaml.cs","summary":"供液槽三维图：液面跟液位，信号灯跟各自的 DI 信号","is3D":true,"project":false,"properties":[{"name":"Tank","type":"TankModel","default":"null","readOnly":false,"twoWay":false,"owner":"TankScene","description":"槽的显示模型（后端 TankDto）","enumValues":[]},{"name":"WallTransparency","type":"Double","default":"0.72","readOnly":false,"twoWay":false,"owner":"TankScene","description":"罐壁透明度（0～1），外部按需要调","enumValues":[]}],"members":[],"variants":[{"label":"基础示例","values":{},"image":"TankScene-0.png","mesh":"TankScene-0.mesh.js"}],"error":null,"example":"<hardware:TankScene\n    Tank=\"{Binding Tank}\"\n    WallTransparency=\"0.72\" />","group":"3D 组合视图"}],"styles":["Color","DarkColors","FontSize","TextBlockStyles","BorderStyles","TextBoxStyles","ComboBoxStyles","DatePickerStyles","ButtonStyles","CardStyles","DataGridStyles","ListBoxStyles","TreeViewStyles"],"schemas":["TankModel","DiSensorModel","WaferModel","RobotArmModel","TrendSeries","ProgressState"],"resourceFiles":["Color","DarkColors","FontSize","TextBlockStyles","BorderStyles","TextBoxStyles","ComboBoxStyles","DatePickerStyles","ButtonStyles","CardStyles","DataGridStyles","ListBoxStyles","TreeViewStyles"]};
